function syncMetric(f:ReturnType<typeof fixture>,label:string,host='browser-sync-progress'){const target=Array.from(f.el(host).querySelectorAll('[data-sync-metric-label]')).find(node=>!node.parentElement?.hidden&&node.textContent===label);assert.ok(target,'progress metric exists: '+label);return Number(target.parentElement?.querySelector('[data-sync-metric-value]')?.textContent);}
function progressText(f:ReturnType<typeof fixture>,host='browser-sync-progress'){return f.el(host).textContent||'';}

type DetailTab='work'|'personal'|'manage';
function detailTab(f:ReturnType<typeof fixture>,tab:DetailTab){const button=f.el('detail-dialog').querySelector('[data-douban-detail-tab="'+tab+'"]');assert.ok(button,'detail tab exists: '+tab);(button as HTMLElement).focus();button.dispatchEvent(new f.window.Event('click',{bubbles:true,cancelable:true}));return button;}
function openClassificationPanel(f:ReturnType<typeof fixture>){detailTab(f,'manage');const panel=f.el('classification-panel');assert.ok(panel);panel.setAttribute('open','');}
function detailPanel(f:ReturnType<typeof fixture>,tab:DetailTab){return f.el('detail-panel-'+tab);}
function detailKey(f:ReturnType<typeof fixture>,tab:DetailTab,key:string){const button=f.el('detail-dialog').querySelector('[data-douban-detail-tab="'+tab+'"]');assert.ok(button);(button as HTMLElement).focus();const event=new f.window.Event('keydown',{bubbles:true,cancelable:true});Object.defineProperty(event,'key',{value:key});button.dispatchEvent(event);return event;}

