function restrictedRun(){return{...run('partial',4),sources:{screen:{status:'failed',pages:0,received:0,total:null,errorCode:'DOUBAN_SOURCE_TIMEOUT'},book:{status:'blocked',pages:0,received:0,total:null,errorCode:'DOUBAN_SOURCE_BLOCKED'},music:{status:'complete',pages:1,received:2,total:2,errorCode:null}},rss:{status:'failed',received:0,errorCode:'DOUBAN_SOURCE_BLOCKED'}};}

function extensionProgress(status='running',pages=0,received=0){return{status,sources:{screen:{status:status==='running'?'pending':'complete',pages,received,total:received},book:{status:status==='running'?'pending':'complete',pages:0,received:0,total:0},music:{status:status==='running'?'pending':'complete',pages:0,received:0,total:0}},pages,received,accountProfileId:'mine'};}
function replyExtension(message:Record<string,unknown>,reply:(value:unknown)=>void,items:Array<Record<string,unknown>>=[],done=true){if(message.action==='CONNECT')reply({ok:true,data:{extensionVersion:'1.0.3',protocolVersion:1}});else if(message.action==='START')reply({ok:true,data:{runId:RUN_ID,step:0,progress:extensionProgress(),done:false}});else if(message.action==='STEP')reply({ok:true,data:{runId:RUN_ID,step:Number(message.step)+1,items:items.map(item=>({...item,url:'https://'+(item.domain==='screen'?'movie':item.domain)+'.douban.com/subject/'+item.subjectId+'/'})),progress:extensionProgress(done?'completed':'running',Number(message.step)+1,items.length),done}});else if(message.action==='LOGIN')reply({ok:true,data:{opened:true}});else if(message.action==='CANCEL')reply({ok:true,data:{cancelled:true}});else assert.fail('Unexpected extension action '+message.action);}
function queuedRecords(count:number){return Array.from({length:count},(_,index)=>({...record,subjectId:String(100001+index),title:'自动分类作品'+index,kind:'screen',source:'import',coverUrl:'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p'+(100001+index)+'.jpg'}));}
function replyAutoExtension(message:Record<string,unknown>,reply:(value:unknown)=>void,items:Array<Record<string,unknown>>=[],done=true){if(message.action==='CONNECT')reply({ok:true,data:{extensionVersion:'1.0.4',protocolVersion:1}});else if(message.action==='SUBJECT')reply({ok:true,data:{requestId:message.requestId,domain:message.domain,subjectId:message.subjectId,metadata:{kind:message.domain==='screen'?(Number(message.subjectId)%2?'movie':'series'):message.domain,coverUrl:'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p'+message.subjectId+'.jpg',details:{year:2026}}}});else if(message.action==='SUBJECT_CANCEL')reply({ok:true,data:{cancelled:true}});else replyExtension(message,reply,items,done);}
const syntheticTmdb={imdbId:'tt1234567',mediaType:'movie',tmdbId:123,posterPath:'/synthetic.jpg',language:'zh',matchedAt:STAMP};
function replyImdbExtension(message:Record<string,unknown>,reply:(value:unknown)=>void,items:Array<Record<string,unknown>>=[]){if(message.action==='CONNECT')reply({ok:true,data:{extensionVersion:'1.0.6',protocolVersion:1}});else if(message.action==='SUBJECT')reply({ok:true,data:{requestId:message.requestId,domain:message.domain,subjectId:message.subjectId,metadata:{kind:'movie',coverUrl:'https://img1.doubanio.com/view/photo/public/p'+message.subjectId+'.jpg',details:{imdbId:'tt1234567',year:2026,privateField:'NEVER-SEND-IMDB-PRIVATE'}}}});else replyAutoExtension(message,reply,items);}

