test('explicitly skipping a metadata version conflict also removes that stale work from the final IMDb batch',async()=>{
 const rows=ratingsSyncRows(2),f=fixture({extension:true,items:rows});await settle(()=>!f.el('browser-sync').disabled);installRatingsSync(f,rows);f.setMetadataHandler(async body=>{const current=f.items().find(item=>item.subjectId===body.subjectId)!;if(body.subjectId===rows[0].subjectId){f.setItems(f.items().map(item=>item===current?{...item,updatedAt:'2026-11-15T02:00:00.000Z'}:item));return Response.json({error:'Synthetic concurrent metadata edit',code:'DOUBAN_RECORD_CONFLICT'},{status:409});}const metadata=body.metadata as {kind:string;coverUrl:string;details:Record<string,unknown>},item={...current,kind:metadata.kind,coverUrl:metadata.coverUrl,details:{...(current.details as object),...metadata.details},updatedAt:'2026-11-14T08:00:01Z'};f.setItems(f.items().map(value=>value===current?item:value));return Response.json({item,changed:true,dataEpoch:0,metadata:{status:'complete'}});});f.setImdbHandler(async body=>{const commands=body.items as Array<{subjectId:string}>;assert.deepEqual(commands.map(item=>item.subjectId),[rows[1].subjectId]);return Response.json(syntheticRatingBatch(f,body));});
 f.click('browser-sync');await settle(()=>f.el('browser-sync').textContent==='跳过冲突并继续同步'&&!f.el('browser-sync').disabled);assert.equal(f.requests.filter(request=>request.path==='/api/life/douban/imdb-ratings').length,0);f.click('browser-sync');await settle(()=>f.el('browser-status').textContent?.startsWith('收藏记录已同步，自动补全仍有未完成条目')===true&&!f.el('browser-sync').disabled);assert.equal(f.requests.filter(request=>request.path==='/api/life/douban/imdb-ratings').length,1);assert.equal(f.requests.filter(request=>request.path==='/api/life/douban/metadata').length,2);assert.equal(syncMetric(f,'更新IMDb'),1);assert.equal(f.items()[0].imdb,undefined);
});

test('account and epoch changes discard late IMDb batch results without continuing the old rating queue',async()=>{
 for(const mode of ['account','epoch']){const rows=ratingsSyncRows(2),f=fixture({extension:true,items:rows});await settle(()=>!f.el('browser-sync').disabled);installRatingsSync(f,rows);let finish!:(response:Response)=>void,body!:Record<string,unknown>;f.setImdbHandler(command=>new Promise(resolve=>{body=command;finish=resolve;}));f.click('browser-sync');await settle(()=>Boolean(finish));const items=f.items().map(item=>presentFixtureRecord(item)),reply={items,dataEpoch:0,receipt:{requestId:body.requestId,requested:2,updated:0,missing:2,checkedAt:'2026-11-15T01:00:00.000Z'},ratings:{status:'complete',source:'imdb-datasets'}};
  if(mode==='account'){f.session.changed=true;f.document.dispatchEvent(new f.window.Event('jiashu-account-changed'));}else{f.setDataEpoch(1);f.setItems([]);f.setConnection({...initialConnection,revision:2});f.submit('search-form');await settle(()=>f.el('list').children.length===0);}finish(Response.json(reply));await settle(()=>f.el('browser-stop').hidden);assert.equal(f.requests.filter(request=>request.path==='/api/life/douban/imdb-ratings').length,1);assert.equal(f.extensionCalls.filter(call=>call.message.action==='SUBJECT').length,2);if(mode==='account')assert.equal(f.el('browser-sync').disabled,true);else{assert.equal(f.el('list').children.length,0);assert.match(f.el('browser-status').textContent??'',/不会恢复旧记录/);}}
});

