 openCoverDetail(f);coverElement(f,'[data-douban-cover-original]').dispatchEvent(new f.window.Event('click',{bubbles:true}));assert.equal(f.requests.filter(request=>request.path==='/api/life/douban/cover-selection').length,1,'restore is a draft until explicit save');f.submit('cover-form');await settle(()=>f.el('list').querySelector('img')?.getAttribute('src')?.startsWith('/api/life/douban/cover?')===true);assert.equal(f.items()[0].coverUrl,latest);assert.equal((f.items()[0].cover as {mode:string}).mode,'original');assert.equal(f.el('detail-body').querySelector('[data-douban-detail-cover]')?.getAttribute('src'),'/api/life/douban/cover?profileId=mine&domain=screen&subjectId=12345');
