test('cover, personal notes and classification drafts each require confirmation before closing the same detail',async()=>{
 const f=fixture();await settle(()=>f.el('list').children.length===1);openCoverDetail(f);detailTab(f,'personal');const note=coverElement(f,'[data-douban-note]');note.value='未保存备注';note.dispatchEvent(new f.window.Event('input',{bubbles:true}));openClassificationPanel(f);f.change('classification-kind','series');const mode=coverElement(f,'[data-douban-cover-mode]');mode.value='url';mode.dispatchEvent(new f.window.Event('change',{bubbles:true}));const input=coverElement(f,'[data-douban-cover-url]');input.value=selectedCoverURL;input.dispatchEvent(new f.window.Event('input',{bubbles:true}));detailTab(f,'work');const cancel=new f.window.Event('cancel',{cancelable:true});f.el('detail-dialog').dispatchEvent(cancel);assert.equal(cancel.defaultPrevented,true);
 for(let remaining=3;remaining>0;remaining--){assert.equal(f.el('detail-dialog').hasAttribute('open'),true);assert.equal(f.confirmations.length,1);f.confirmations.shift()!();}assert.equal(f.el('detail-dialog').hasAttribute('open'),false);assert.equal(f.requests.filter(request=>request.method!=='GET').length,0);
});

