test('explicit page refresh keeps cumulative metadata progress when paused, read again and resumed',async()=>{
 const checkedAt=new Date(Date.now()-60000).toISOString(),rows=[0,1].map(index=>({...record,domain:'book',kind:'book',subjectId:String(771000+index),coverUrl:'https://img1.doubanio.com/view/subject/l/public/s'+index+'.jpg',details:{summary:'已完整的书籍资料',authors:['合成作者']},sync:{collectionHash:'b'.repeat(64),detailsCheckedAt:checkedAt}})),f=fixture({items:rows});await settle(()=>!f.el('metadata-refresh').disabled);let finish!:()=>void;let calls=0;
 f.setMetadataHandler(body=>{const old=f.items().find(item=>item.subjectId===body.subjectId)!,item={...old,details:{...(old.details as object),summary:'显式刷新的资料'},updatedAt:new Date().toISOString(),sync:{...(old.sync as object),detailsCheckedAt:new Date().toISOString()}};f.setItems(f.items().map(value=>value===old?item:value));const response=Response.json({item:presentFixtureRecord(item),changed:true,dataEpoch:0,metadata:{status:'complete'}});calls++;return calls===1?new Promise<Response>(resolve=>{finish=()=>resolve(response);}):Promise.resolve(response);});
 f.click('metadata-refresh');await settle(()=>Boolean(finish));f.click('metadata-stop');finish();await settle(()=>f.el('metadata-progress').dataset.state==='paused'&&!f.el('metadata-resume').disabled);assert.equal(syncMetric(f,'已核对','metadata-progress'),1);assert.equal(syncMetric(f,'已更新','metadata-progress'),1);assert.equal(f.el('metadata-progress').querySelector('[data-sync-bar]')?.getAttribute('value'),'1');assert.equal(f.el('metadata-progress').querySelector('[data-sync-bar]')?.getAttribute('max'),'2');f.submit('search-form');await settle(()=>f.el('page').getAttribute('aria-busy')==='false');assert.equal(calls,1);
 f.click('metadata-resume');await settle(()=>f.el('metadata-progress').dataset.phase==='done'&&f.el('metadata-progress').dataset.state==='done');assert.equal(calls,2);assert.equal(syncMetric(f,'已核对','metadata-progress'),2);assert.equal(syncMetric(f,'已更新','metadata-progress'),2);assert.deepEqual(f.requests.filter(request=>request.path==='/api/life/douban/metadata').map(request=>request.body?.subjectId),rows.map(item=>item.subjectId));assert.equal(f.requests.filter(request=>request.path==='/api/life/douban/tmdb'||request.path==='/api/life/douban/imdb-ratings').length,0);
});

